actions.script:
importedRunId = null
if (!context.resultFile) {
    ec.message.addError(ec.l10n.localize('Choose a result file'))
} else {
    const imported = ec.resource.script('component://tools/template/LoadRuns.js').call('import#LoadRunResult',
        {result: String(resultFile.getString() || ''), label: context.importLabel || null})
    if (imported.error) ec.message.addError(imported.error)
    else importedRunId = imported.out.runId
}

const lib = ec.resource.script('component://tools/template/LoadRuns.js')
const listed = lib.call('find#LoadRuns', {scriptLocation: context.scriptLocation || null, status: context.status || null})
runsError = listed.error
const scripts = lib.call('find#LoadScripts').out.scripts || []
const titles = Object.fromEntries(scripts.map((script) => [String(script.location), String(script.title || script.name || '')]))
scriptOptions = scripts.map((script) => ({key: String(script.location), text: String(script.title || script.name || '') + ' (' + String(script.componentName || '') + ')'}))
const statuses = {running: ['Running', 'primary'], completed: ['Completed', 'positive'], stopped: ['Stopped', 'warning'], failed: ['Failed', 'negative']}
const kinds = {service: "This server's services", this: 'This server'}
// a run's start, an RFC 3339 text or epoch milliseconds, as a timestamp
const DIGITS = /^[0-9]+$/, SCRIPT_DIR = /^.*\//, LOAD_JS = /\.load\.js$/
const stamp = (value) => {
    if (value == null || value === '') return null
    try { return basicConvert(DIGITS.test(String(value)) ? Number(value) : String(value), 'Timestamp') } catch (e) { return null }
}
const time = (value) => { const at = stamp(value); return at == null ? '' : ec.l10n.format(at, 'yyyy-MM-dd HH:mm:ss') }
// the day a run started in the user's time zone, against the day asked for
const day = (value) => { const at = stamp(value); return at == null ? '' : String(ec.l10n.format(at, 'yyyy-MM-dd')) }
const from = context.startedFrom ? String(context.startedFrom).slice(0, 10) : ''
// the runs asked for, then a row for each run of the page only (its start formatted, its script's title)
const all = from ? (listed.out.runs || []).filter((run) => { const started = day(run.start); return !!started && started >= from })
    : (listed.out.runs || [])
const row = (run) => {
    const status = statuses[run.status] || [String(run.status || ''), 'grey-7']
    const script = String(run.script || '')
    return {runId: String(run.runId || ''), scriptTitle: titles[script] || script.replace(SCRIPT_DIR, '').replace(LOAD_JS, ''),
        label: String(run.label || ''), targetText: kinds[run.targetKind] || String(run.target || ''), statusText: status[0], statusColor: status[1],
        start: String(run.start || ''), startText: time(run.start), users: run.users, requests: run.requests, rps: run.rps, errors: run.errors,
        p95: run.p95, user: String(run.user || ''), finished: run.status != 'running'}
}
const pageSize = Math.min(100, Math.max(1, Number(context.pageSize) || 20))
const pageMaxIndex = Math.max(0, Math.ceil(all.length / pageSize) - 1)
const pageIndex = Math.min(pageMaxIndex, Math.max(0, Number(context.pageIndex) || 0))
runList = all.slice(pageIndex * pageSize, (pageIndex + 1) * pageSize).map(row)
runListCount = all.length
runListPageIndex = pageIndex
runListPageSize = pageSize
runListPageMaxIndex = pageMaxIndex
runListPageRangeLow = all.length ? pageIndex * pageSize + 1 : 0
runListPageRangeHigh = Math.min(all.length, (pageIndex + 1) * pageSize)
